#!/usr/bin/env python3
# =============================================================================
# sprite_walk_unifont.py  --  CLIPasso/Unifont walk and horse viewer
# =============================================================================
# A thin wrapper around sprite_idle.py's terminal viewer that displays the
# 8-direction WALK cycle and the 8-direction horse pose set as 5x7 GNU-Unifont
# ASCII.
#
# The frames are generated by .scratch/CLIPasso/sheet_unifont_5x7.py from the
# CLIPasso walk outlines. Each frame is matched against the pinned Unifont atlas
# at a 5-wide x 7-tall grid. The blocks live in
# scripts/sprite_frames_walk_5x7_unifont.txt using the same # DIR and
# blank-line-separated format sprite_idle.py already understands.
#
# All TUI behaviour (rotation, walk-cycle stepping, centroid planting, controls)
# is reused unchanged from sprite_idle. This launcher owns dataset selection,
# validates the complete 8-direction 5x7 contract, then replaces the embedded
# fallback poses before curses starts.
#
# USE
#   python3 scripts/sprite_walk_unifont.py            # play the walk
#   python3 scripts/sprite_walk_unifont.py --sprite horse
#   python3 scripts/sprite_walk_unifont.py --fps 6    # faster
#   python3 scripts/sprite_walk_unifont.py --sprite horse --check
#   (hold a direction to cycle its walk frames; same keys as sprite_idle)
#
# NOTE: your terminal needs broad Unicode coverage to render the admitted
# Unifont vocabulary.
# =============================================================================
from __future__ import annotations

import argparse
import curses
import locale
import os

import sprite_idle as si          # same directory (scripts/) is on sys.path[0]

locale.setlocale(locale.LC_ALL, "")

FRAME_FILES = {
    "walk": "sprite_frames_walk_5x7_unifont.txt",
    "horse": "sprite_frames_horse_5x7_unifont.txt",
}


def validate_frames(loaded: dict, path: str) -> None:
    missing = [direction for direction in si.ORDER if direction not in loaded]
    if missing:
        raise ValueError(f"{path}: missing directions: {', '.join(missing)}")
    for direction in si.ORDER:
        if not loaded[direction]:
            raise ValueError(f"{path}: {direction} has no frames")
        for frame_index, frame in enumerate(loaded[direction], start=1):
            rows = frame.splitlines()
            if len(rows) != 7:
                raise ValueError(
                    f"{path}: {direction} frame {frame_index} has {len(rows)} rows; expected 7"
                )
            bad_widths = [len(row) for row in rows if len(row) != 5]
            if bad_widths:
                raise ValueError(
                    f"{path}: {direction} frame {frame_index} is not exactly 5 columns"
                )


def main() -> int:
    here = os.path.dirname(os.path.abspath(__file__))
    ap = argparse.ArgumentParser(
        description="Display the 8-direction walk cycle or horse rotations as 5x7 Unifont ASCII.")
    ap.add_argument("--sprite", choices=tuple(FRAME_FILES), default="walk",
                    help="compiled sprite set to display (default: walk)")
    ap.add_argument("--fps", type=float, default=4.0, help="walk speed frames/sec (default 4)")
    ap.add_argument("--frames", help="explicit viewer frame file")
    ap.add_argument("--check", action="store_true",
                    help="validate the selected frame file without opening curses")
    args = ap.parse_args()

    frames_path = args.frames or os.path.join(here, FRAME_FILES[args.sprite])
    loaded = si.load_frames_txt(frames_path)
    validate_frames(loaded, frames_path)
    if args.check:
        counts = ", ".join(f"{direction}={len(loaded[direction])}" for direction in si.ORDER)
        print(f"valid {args.sprite} 5x7 frame set: {counts}")
        return 0

    # The compiled file is the sole frame owner in this launcher. Remove the
    # sprite_idle fallback before installing the validated set.
    si.FRAMES.clear()
    si.FRAMES.update(loaded)

    # Wire the 5x7 sprite box and pelvis pivot before the shared viewer starts.
    si.TARGET_W = 5                       # box WIDTH in glyphs (5x7 sprite)
    si.TARGET_H = 7                       # box HEIGHT in glyphs (5x7 sprite)
    si.PELVIS_COL = si.TARGET_W // 2      # centre column -> 2 for a 5-wide box
    si.PELVIS_ROW = 5                     # hip/legs row of a 7-row pose (was 3 for 5 rows)

    curses.wrapper(si.run, args.fps)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
